{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Pirprofen, a chlorinated 2-arylpropionic acid, showed high and uniform oral bioavailability in volunteers, directly supporting high F for the similarly chlorinated propionic acid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Naproxen, a 2-arylpropionic acid NSAID, has 99% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Flurbiprofen, a halogenated 2-arylpropionic acid, is almost completely available (~92%) after oral administration in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Ketoprofen, a 2-arylpropionic acid, has absolute oral bioavailability ≥92% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ibuprofen, a 2-arylpropionic acid, is essentially 100% bioavailable after oral dosing compared with IV in humans, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carprofen, a 2-arylpropionic acid NSAID. All close structural analogues (pirprofen, naproxen, flurbiprofen, ketoprofen, ibuprofen) have high or complete oral bioavailability in humans, with absolute F values mostly 80–100%. The carboxylic acid ionization does not prevent absorption in this class. Therefore, F ≥20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for carprofen itself in the provided evidence set.",
    "One ibuprofen record (C24) reports 25% bioavailability, but this is inconsistent with multiple IV-referenced studies and likely formulation-specific; it does not change the class-level conclusion.",
    "Species differences may exist because carprofen is commonly used in veterinary medicine, but human data for the analogue class are strong."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

